"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[84355],{6239:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>r,contentTitle:()=>s,default:()=>c,frontMatter:()=>i,metadata:()=>a,toc:()=>d});var o=n(31085),h=n(71184);const i={sidebar_position:5,slug:"/bible/1_John/1_John_5",title:"1 John 5",hide_table_of_contents:!0},s="1 John",a={id:"bible/1 John/1 John 5",title:"1 John 5",description:"Chapter 5",source:"@site/docs/bible/1 John/1 John 5.md",sourceDirName:"bible/1 John",slug:"/bible/1_John/1_John_5",permalink:"/docs/bible/1_John/1_John_5",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/1 John/1 John 5.md",tags:[],version:"current",sidebarPosition:5,frontMatter:{sidebar_position:5,slug:"/bible/1_John/1_John_5",title:"1 John 5",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"1 John 4",permalink:"/docs/bible/1_John/1_John_4"},next:{title:"2 John",permalink:"/docs/bible/2 John/"}},r={},d=[{value:"Chapter 5",id:"chapter-5",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,h.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.h1,{id:"1-john",children:"1 John"}),"\n",(0,o.jsx)(t.h2,{id:"chapter-5",children:"Chapter 5"}),"\n",(0,o.jsx)(t.p,{children:"Of them that are born of God, and of true charity.  Faith overcomes the world.  Three that bear witness to Christ.  Of faith in his name and of sin that is and is not to death."}),"\n",(0,o.jsx)(n,{verse:1,children:"Whosoever believeth that Jesus is the Christ, is born of God. And every one that loveth him who begot, loveth him also who is born of him."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: Is born of God...That is, is justified, and become a child of God by baptism: which is also to be understood; provided the belief of this fundamental article of the Christian faith be accompanied with all the other conditions, which, by the word of God, and his appointment, are also required to justification; such as a general belief of all that God has revealed and promised: hope, love, repentance, and a sincere disposition to keep God's holy law and commandments."})}),"\n",(0,o.jsx)(n,{verse:2,children:"In this we know that we love the children of God: when we love God and keep his commandments."}),"\n",(0,o.jsx)(n,{verse:3,children:"For this is the charity of God: That we keep his commandments. And his commandments are not heavy."}),"\n",(0,o.jsx)(n,{verse:4,children:"For whatsoever is born of God overcometh the world. And this is the victory which overcameth the world: Our faith."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: Our faith...Not a bare, speculative, or dead faith; but a faith that worketh by charity. Gal. 5.6"})}),"\n",(0,o.jsx)(n,{verse:5,children:"Who is he that overcometh the world, but he that believeth that Jesus is the Son of God?"}),"\n",(0,o.jsx)(n,{verse:6,children:"This is he that came by water and blood, Jesus Christ: not by water only but by water and blood. And it is the Spirit which testifieth that Christ is the truth."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: Came by water and blood...Not only to wash away our sins by the water of baptism, but by his own blood."})}),"\n",(0,o.jsx)(n,{verse:7,children:"And there are Three who give testimony in heaven, the Father, the Word, and the Holy Ghost. And these three are one."}),"\n",(0,o.jsx)(n,{verse:8,children:"And there are three that give testimony on earth: the spirit and the water and the blood. And these three are one."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: The spirit, and the water, and the blood...As the Father, the Word, and the Holy Ghost, all bear witness to Christ's divinity; so the spirit, which he yielded up, crying out with a loud voice upon the cross; and the water and blood that issued from his side, bear witness to his humanity, and are one; that is, all agree in one testimony."})}),"\n",(0,o.jsx)(n,{verse:9,children:"If we receive the testimony of men, the testimony of God is greater. For this is the testimony of God, which is greater, because he hath testified of his Son."}),"\n",(0,o.jsx)(n,{verse:10,children:"He that believeth in the Son of God hath the testimony of God in himself. He that believeth not the Son maketh him a liar: because he believeth not in the testimony which God hath testified of his Son."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: He that believeth not the Son, etc...By refusing to believe the testimonies given by the three divine persons, that Jesus was the Messias, and the true Son of God, by whom eternal life is obtained and promised to all that comply with his doctrine. In him we have also this lively confidence, that we shall obtain whatever we ask, according to his will, when we ask what is for our good, with perseverance, and in the manner we ought. And this we know, and have experience of, by having obtained the petitions that we have made."})}),"\n",(0,o.jsx)(n,{verse:11,children:"And this is the testimony that God hath given to us eternal life. And this life is in his Son."}),"\n",(0,o.jsx)(n,{verse:12,children:"He that hath the Son hath life. He that hath not the Son hath not life."}),"\n",(0,o.jsx)(n,{verse:13,children:"These things I write to you that you may know that you have eternal life: you who believe in the name of the Son of God."}),"\n",(0,o.jsx)(n,{verse:14,children:"And this is the confidence which we have towards him: That, whatsoever we shall ask according to his will, he heareth us."}),"\n",(0,o.jsx)(n,{verse:15,children:"And we know that he heareth us whatsoever we ask: we know that we have the petitions which we request of him."}),"\n",(0,o.jsx)(n,{verse:16,children:"He that knoweth his brother to sin a sin which is not to death, let him ask: and life shall be given to him who sinneth not to death. There is a sin unto death. For that I say not that any man ask."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: A sin which is not to death, etc...It is hard to determine what St. John here calls a sin which is not to death, and a sin which is unto death. The difference can not be the same as betwixt sins that are called venial and mortal: for he says, that if a man pray for his brother, who commits a sin that is not to death, life shall be given him: therefore such a one had before lost the life of grace, and been guilty of what is commonly called a mortal sin. And when he speaks of a sin that is unto death, and adds these words, for that I say not that any man ask, it cannot be supposed that St. John would say this of every mortal sin, but only of some heinous sins, which are very seldom remitted, because such sinners very seldom repent. By a sin therefore which is unto death, interpreters commonly understand a wilfull apostasy from the faith, and from the known truth, when a sinner, hardened by his own ingratitude, becomes deaf to all admonitions, will do nothing for himself, but runs on to a final impenitence. Nor yet does St. John say, that such a sin is never remitted, or cannot be remitted, but only has these words, for that I say not that any man ask the remission : that is, though we must pray for all sinners whatsoever, yet men can not pray for such sinners with such a confidence of obtaining always their petitions, as St. John said before, ver. 14. Whatever exposition we follow on this verse, our faith teacheth us from the holy scriptures, that God desires not the death of any sinner, but that he be converted and live, Ezech. 33.11. Though men's sins be as red as scarlet, they shall become as white as snow, Isa. 3.18. It is the will of God that every one come to the knowledge of the truth, and be saved. There is no sin so great but which God is willing to forgive, and has left a power in his church to remit the most enormous sins: so that no sinner need despair of pardon, nor will\nNote 2: any sinner perish, but by his own fault. A sin unto death...Some understand this of final impenitence, or of dying in mortal sin; which is the only sin that never can be remitted. But, it is probable, he may also comprise under this name, the sin of apostasy from the faith, and some other such heinous sins as are seldom and hardly remitted: and therefore he gives little encouragement, to such as pray for these sinners, to expect what they ask."})}),"\n",(0,o.jsx)(n,{verse:17,children:"All iniquity is sin. And there is a sin unto death."}),"\n",(0,o.jsx)(n,{verse:18,children:"We know that whosoever is born of God sinneth not: but the generation of God preserveth him and the wicked one toucheth him not."}),"\n",(0,o.jsx)(n,{verse:19,children:"We know that we are of God and the whole world is seated in wickedness."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: And the whole world is seated in wickedness...That is, a great part of the world. It may also signify, is under the wicked one, meaning the devil, who is elsewhere called the prince of this world, that is, of all the wicked. John 12.31."})}),"\n",(0,o.jsx)(n,{verse:20,children:"And we know that the Son of God is come. And he hath given us understanding that we may know the true God and may be in his true Son. This is the true God and life eternal. And may be in his true Son. He is, or this is the true God, and life"}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: eternal...Which words are a clear proof of Christ's divinity, and as such made use of by the ancient fathers."})}),"\n",(0,o.jsx)(n,{verse:21,children:"Little children, keep yourselves from idols. Amen."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: Keep yourselves from idols...An admonition to the newly converted Christians, lest conversing with heathens and idolaters, they might fall back into the sin of idolatry, which may be the sin unto death here mentioned by St. John."})})]})}function c(e={}){const{wrapper:t}={...(0,h.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>a});var o=n(14041);const h={},i=o.createContext(h);function s(e){const t=o.useContext(i);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(h):e.components||h:s(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);